def test_hyb_mgga_x_m06_hf_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m06_hf", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.574628280525300e+00, 1.493736508323739e+00, 1.373139781863679e+00, 1.199603519237706e+00, 9.724223755503582e-01, 7.351431848900201e-01, 5.786131819080130e-01, 3.953708465268850e-01, -5.860126704963338e-02, -2.056682028662052e-01, -4.439659785950409e-01, -1.391837063022680e-01, 5.739531679279115e-02, 4.601996037631952e-02, -3.804352547536874e-02, -9.832615724153609e-02, -5.476635622159934e-02, 6.086172759881482e-02, 1.895179831037179e-02, 2.167868269723002e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


